fn square(n: i32) -> i32 {
    n * n
}

fn describe(n: i32) {
    println!("{n} squared is {}", square(n));
}

fn main() {
    describe(4);
    describe(9);
}

fn safe_divide(a: i32, b: i32) -> i32 {
    if b == 0 {
        return 0;
    }
    a / b
}

fn main() {
    println!("{}", safe_divide(10, 2));
    println!("{}", safe_divide(10, 0));
}

fn min_max(a: i32, b: i32) -> (i32, i32) {
    if a < b { (a, b) } else { (b, a) }
}

fn main() {
    let (low, high) = min_max(8, 3);
    println!("low {low}, high {high}");
}

