    c + 32.0
}

fn main() {
    println!("{}", celsius_to_fahrenheit(100.0));
}

exercise.solution:
fn celsius_to_fahrenheit(c: f64) -> f64 {
    c * 9.0 / 5.0 + 32.0
}

fn main() {
    println!("{}", celsius_to_fahrenheit(100.0));
}
